    if y % 2 == 0:  # Even row
        return [
            (x, y+1),      # NE
            (x+1, y),      # E
            (x, y-1),      # SE
            (x-1, y-1),    # SW
            (x-1, y),      # W
            (x-1, y+1),    # NW
        ]
    else:  # Odd row
        return [
            (x+1, y+1),    # NE
            (x+1, y),      # E
            (x+1, y-1),    # SE
            (x, y-1),      # SW
            (x-1, y),      # W
            (x, y+1),      # NW
        ]

def get_tiles_in_range(x, y, radius):
    tiles = set()
    tiles.add((x, y))
    frontier = [(x, y)]
    for _ in range(radius):
