import sqlite3
import json
from itertools import combinations, permutations

conn = sqlite3.connect('/data/maps/e2e_test_case_0.Civ6Map')
cursor = conn.cursor()

cursor.execute("SELECT Width, Height FROM Map")
width, height = cursor.fetchone()

cursor.execute("""
    SELECT p.ID, p.TerrainType, p.IsImpassable, f.FeatureType
    FROM Plots p
    LEFT JOIN PlotFeatures f ON p.ID = f.ID
""")

plots = {}
for row in cursor.fetchall():
    plot_id, terrain, impassable, feature = row
    x, y = plot_id % width, plot_id // width
    plots[(x, y)] = {
        'terrain': terrain,
        'impassable': bool(impassable),
        'feature': feature
    }

cursor.execute("SELECT ID, IsNEOfRiver, IsWOfRiver, IsNWOfRiver FROM PlotRivers")
rivers = {}
for row in cursor.fetchall():
    plot_id = row[0]
    x, y = plot_id % width, plot_id // width
    rivers[(x, y)] = True

conn.close()

def get_adjacent_hexes(x, y):
    if y % 2 == 0:
        return [(x, y+1), (x+1, y), (x, y-1), (x-1, y-1), (x-1, y), (x-1, y+1)]
    else:
        return [(x+1, y+1), (x+1, y), (x+1, y-1), (x, y-1), (x-1, y), (x, y+1)]

def get_tiles_in_range(x, y, radius):
    tiles = set()
    tiles.add((x, y))
    frontier = [(x, y)]
    for _ in range(radius):
        new_frontier = []
        for fx, fy in frontier:
            for ax, ay in get_adjacent_hexes(fx, fy):
                if 0 <= ax < width and 0 <= ay < height:
                    if (ax, ay) not in tiles:
                        tiles.add((ax, ay))
                        new_frontier.append((ax, ay))
        frontier = new_frontier
    return tiles

def is_buildable(x, y):
    if (x, y) not in plots:
        return False
    p = plots[(x, y)]
    if 'OCEAN' in p['terrain'] or 'COAST' in p['terrain']:
        return False
    if p['impassable']:
        return False
    if p['feature'] == 'FEATURE_ICE':
        return False
    return True

def is_on_river(x, y):
    return (x, y) in rivers

def calculate_campus_adjacency(x, y, placed_districts, city_center):
    bonus = 0.0
    occupied_tiles = set(placed_districts.keys())
    occupied_tiles.add(city_center)

    for ax, ay in get_adjacent_hexes(x, y):
        if (ax, ay) not in plots:
            continue
        p = plots[(ax, ay)]

        if (ax, ay) in occupied_tiles:
            if (ax, ay) in placed_districts and placed_districts[(ax, ay)] != 'CAMPUS':
                bonus += 0.5
            continue

        feature = p['feature']
        if feature == 'FEATURE_GEOTHERMAL_FISSURE':
            bonus += 2
        if feature == 'FEATURE_REEF':
            bonus += 2
        if p['impassable'] and 'MOUNTAIN' in p['terrain']:
            bonus += 1
        if feature in ['FEATURE_JUNGLE', 'FEATURE_FOREST']:
            bonus += 0.5

    return int(bonus)

def calculate_commercial_hub_adjacency(x, y, placed_districts, city_center):
    bonus = 0.0
    if is_on_river(x, y):
        bonus += 2

    for ax, ay in get_adjacent_hexes(x, y):
        if (ax, ay) not in plots:
            continue
        if (ax, ay) in placed_districts and placed_districts[(ax, ay)] != 'COMMERCIAL_HUB':
            bonus += 0.5

    return int(bonus)

def calculate_holy_site_adjacency(x, y, placed_districts, city_center):
    bonus = 0.0
    occupied_tiles = set(placed_districts.keys())
    occupied_tiles.add(city_center)

    for ax, ay in get_adjacent_hexes(x, y):
        if (ax, ay) not in plots:
