                bonus += 0.5
            continue

        feature = p['feature']
        if p['impassable'] and 'MOUNTAIN' in p['terrain']:
            bonus += 1
        if feature in ['FEATURE_JUNGLE', 'FEATURE_FOREST']:
            bonus += 0.5

    return int(bonus)

def calculate_industrial_zone_adjacency(x, y, placed_districts, city_center):
    bonus = 0.0
    for ax, ay in get_adjacent_hexes(x, y):
        if (ax, ay) not in plots:
            continue
        if (ax, ay) in placed_districts and placed_districts[(ax, ay)] != 'INDUSTRIAL_ZONE':
            bonus += 0.5
    return int(bonus)

def calculate_theater_square_adjacency(x, y, placed_districts, city_center):
    bonus = 0.0
    for ax, ay in get_adjacent_hexes(x, y):
        if (ax, ay) not in plots:
            continue
        if (ax, ay) in placed_districts and placed_districts[(ax, ay)] != 'THEATER_SQUARE':
            bonus += 0.5
    return int(bonus)

def calculate_adjacency(district, x, y, placed_districts, city_center):
    if district == 'CAMPUS':
        return calculate_campus_adjacency(x, y, placed_districts, city_center)
    elif district == 'COMMERCIAL_HUB':
        return calculate_commercial_hub_adjacency(x, y, placed_districts, city_center)
    elif district == 'HOLY_SITE':
        return calculate_holy_site_adjacency(x, y, placed_districts, city_center)
    elif district == 'INDUSTRIAL_ZONE':
        return calculate_industrial_zone_adjacency(x, y, placed_districts, city_center)
    elif district == 'THEATER_SQUARE':
        return calculate_theater_square_adjacency(x, y, placed_districts, city_center)
    return 0

buildable_tiles = [(x, y) for x in range(width) for y in range(height) if is_buildable(x, y)]
district_limit = 3
available_districts = ['CAMPUS', 'COMMERCIAL_HUB', 'INDUSTRIAL_ZONE', 'HOLY_SITE', 'THEATER_SQUARE']

