    workable = get_tiles_in_range(cx, cy, 3)
    available = [t for t in workable if is_buildable(*t) and t != city_center]

    if len(available) < district_limit:
        continue

    for district_combo in combinations(available_districts, district_limit):
        for tile_combo in permutations(available, district_limit):
            placement = {tile_combo[i]: district_combo[i] for i in range(district_limit)}

            total = 0
            bonuses = {}
            for tile, district in placement.items():
                adj = calculate_adjacency(district, tile[0], tile[1], placement, city_center)
                bonuses[district] = adj
                total += adj

            if total >= 9:
                good_solutions.append({
                    'total': total,
                    'city_center': city_center,
                    'placements': {d: t for t, d in placement.items()},
                    'bonuses': bonuses
                })

# Sort by total descending
good_solutions.sort(key=lambda x: -x['total'])

print("Top solutions:")
